// BLOKADA VENDOR PATCH — not part of the upstream package.
//
// The plugin's pubspec declares `pluginClass: AdaptyFlutterPlugin`, which only
// exists as the @objc(AdaptyFlutterPlugin) alias of SwiftAdaptyFlutterPlugin.
// Flutter's Swift plugin registrant (generated by `flutter build
// swift-package`) references the pluginClass name as a Swift identifier, so
// module/add-to-app builds fail with "cannot find 'AdaptyFlutterPlugin' in
// scope". Alias the Swift name. Drop when upstream renames the class or fixes
// the pubspec.
public typealias AdaptyFlutterPlugin = SwiftAdaptyFlutterPlugin
